insert ignore into post_bookmark(user_id, post_id, create_time)
select #{userId, jdbcType=BINARY}, p.id, #{createTime}
from discuss_post p
where p.id = #{postId, jdbcType=BINARY}
  and p.status != 2

mapper.delete:
delete from post_bookmark
where user_id = #{userId, jdbcType=BINARY}
  and post_id = #{postId, jdbcType=BINARY}

